import importlib.abc
import importlib.util

_SOURCES = {"rung":"\"\"\"Rung \u2014 AI Agent Governance Audit Engine.\n\nModular audit engine for scoring repository readiness for AI coding\nagent governance. Produces a deterministic AuditResult v1 from which\nboth free preview and paid PDF projections render.\n\nLicense: MIT\n\"\"\"\n\n__version__ = \"0.2.0\"\n\nfrom rung.audit import run_audit, AuditResult\nfrom rung.scoring import compute_score, GRADE_LABELS\nfrom rung.models import CheckResult, EvidenceState, Confidence, SourceClass, AuthorityLevel\nfrom rung.renderer import render_preview, render_html, render_pdf_data\n\n__all__ = [\n    \"run_audit\",\n    \"AuditResult\",\n    \"compute_score\",\n    \"GRADE_LABELS\",\n    \"CheckResult\",\n    \"EvidenceState\",\n    \"Confidence\",\n    \"SourceClass\",\n    \"AuthorityLevel\",\n    \"render_preview\",\n    \"render_html\",\n    \"render_pdf_data\",\n]","rung.__main__":"\"\"\"Allow running as `python3 -m rung`.\"\"\"\nfrom rung.cli import main\nimport sys\n\nif __name__ == \"__main__\":\n    sys.exit(main())","rung.audit":"\"\"\"Audit orchestrator \u2014 runs all checks and produces AuditResult v1.\n\nThe free preview and paid PDF both render from the same AuditResult.\nIncludes a canonical report-data digest computed over all fields\nexcept the digest itself.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport hashlib\nimport json\nfrom datetime import datetime, timezone\nfrom pathlib import Path\nfrom typing import Optional\n\nfrom rung.models import CheckResult, AuditResult, AuthorityLevel\nfrom rung.scoring import compute_score, recommend_authority, GRADE_LABELS\nfrom rung.checks import ALL_CHECKS\nfrom rung import __version__ as RUNG_VERSION\n\nSCHEMA_VERSION = \"1.0.0\"\n\n\ndef _compute_digest(result_dict: dict) -> str:\n    \"\"\"Compute SHA-256 over canonical JSON of the result, excluding the digest field.\"\"\"\n    data = {k: v for k, v in result_dict.items() if k != \"report_data_sha256\"}\n    canonical = json.dumps(data, sort_keys=True, ensure_ascii=False, separators=(\",\", \":\"))\n    return hashlib.sha256(canonical.encode(\"utf-8\")).hexdigest()\n\n\ndef run_audit(\n    root: Path,\n    commit_sha: Optional[str] = None,\n    repository: Optional[str] = None,\n    timestamp: Optional[str] = None,\n) -> AuditResult:\n    \"\"\"Run all checks against a repository root and return AuditResult v1.\"\"\"\n    root = Path(root).resolve()\n    checks = [check(root) for check in ALL_CHECKS]\n    score, grade, gate = compute_score(checks)\n    authority = recommend_authority(checks)\n    timestamp = timestamp or datetime.now(timezone.utc).strftime(\"%Y-%m-%dT%H:%M:%SZ\")\n\n    result = AuditResult(\n        repository=repository or str(root),\n        commit_sha=commit_sha,\n        checks=checks,\n        score=score,\n        grade=grade,\n        grade_label=GRADE_LABELS.get(grade, \"\"),\n        quality_gate=\"PASS\" if gate else \"FAIL\",\n        authority=authority,\n        rung_version=RUNG_VERSION,\n        schema_version=SCHEMA_VERSION,\n        timestamp=timestamp,\n    )\n\n    result_dict = result_to_dict(result)\n    result.report_data_sha256 = _compute_digest(result_dict)\n    return result\n\n\ndef result_to_dict(result: AuditResult) -> dict:\n    \"\"\"Convert AuditResult to a JSON-serializable dict.\"\"\"\n    return {\n        \"repository\": result.repository,\n        \"commit_sha\": result.commit_sha,\n        \"score\": result.score,\n        \"grade\": result.grade,\n        \"grade_label\": result.grade_label,\n        \"quality_gate\": result.quality_gate,\n        \"authority\": result.authority.value if isinstance(result.authority, AuthorityLevel) else str(result.authority),\n        \"rung_version\": result.rung_version,\n        \"schema_version\": result.schema_version,\n        \"timestamp\": result.timestamp,\n        \"report_data_sha256\": result.report_data_sha256,\n        \"checks\": [check_to_dict(c) for c in result.checks],\n    }\n\n\ndef check_to_dict(c: CheckResult) -> dict:\n    \"\"\"Convert CheckResult to a JSON-serializable dict.\"\"\"\n    return {\n        \"name\": c.name,\n        \"description\": c.description,\n        \"weight\": c.weight,\n        \"blocking\": c.blocking,\n        \"state\": c.state.value if hasattr(c.state, \"value\") else str(c.state),\n        \"confidence\": c.confidence.value if hasattr(c.confidence, \"value\") else str(c.confidence),\n        \"blocking_for\": c.blocking_for,\n        \"evidence\": c.evidence,\n        \"limitations\": c.limitations,\n        \"remediation\": c.remediation,\n        \"source_mappings\": c.source_mappings,\n        \"passed\": c.passed,\n    }\n","rung.checks":"\"\"\"Rung governance checks.\n\nEach check returns a CheckResult with evidence states instead of\nboolean pass/fail. Checks are registered in ALL_CHECKS.\n\"\"\"\n\nfrom rung.checks.agent_policy import check_agent_policy\nfrom rung.checks.build_commands import check_build_commands\nfrom rung.checks.verification_gate import check_verification_gate\nfrom rung.checks.source_registry import check_source_registry\nfrom rung.checks.evidence_traceability import check_evidence_traceability\nfrom rung.checks.session_ledger import check_session_ledger\nfrom rung.checks.file_size import check_file_size\nfrom rung.checks.agent_attribution import check_agent_attribution\nfrom rung.checks.security_never_rules import check_security_never_rules\nfrom rung.checks.independent_review import check_independent_review\nfrom rung.checks.cyclic_verification import check_cyclic_verification\n\nALL_CHECKS = [\n    check_agent_policy,\n    check_build_commands,\n    check_verification_gate,\n    check_source_registry,\n    check_evidence_traceability,\n    check_session_ledger,\n    check_file_size,\n    check_agent_attribution,\n    check_security_never_rules,\n    check_independent_review,\n    check_cyclic_verification,\n]","rung.checks.agent_attribution":"\"\"\"Check 8: Agent attribution on commits/PRs.\"\"\"\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import read_text, has_affirmative_pattern\n\n\ndef check_agent_attribution(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Agent attribution\",\n        description=\"Convention for attributing AI-assisted commits and PRs (Generated-by / Co-authored-by)\",\n        weight=5, blocking=False,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.MEDIUM,\n        source_mappings=[\n            {\"id\": \"apache_airflow\", \"classification\": SOURCES[\"apache_airflow\"][\"classification\"].value},\n        ],\n    )\n    patterns = [r'Generated-by:', r'Co-authored-by:', r'Drafted-by:', r'AI-assisted', r'agent-assisted']\n    files_to_check = [root / \"AGENTS.md\", root / \".github\" / \"pull_request_template.md\", root / \"CONTRIBUTING.md\"]\n    found = False\n    for f in files_to_check:\n        if f.exists():\n            content = read_text(f)\n            if content is None:\n                continue\n            if has_affirmative_pattern(content, patterns):\n                found = True\n                r.evidence.append(f\"Attribution convention in {f.relative_to(root)}\")\n    if found:\n        r.state = EvidenceState.DETECTED\n    else:\n        r.remediation = [\n            \"Add an attribution convention to AGENTS.md or PR template:\",\n            \"  Generated-by: <Agent Name and Version>\",\n        ]\n    return r\n","rung.checks.agent_policy":"\"\"\"Check 1: Agent policy file exists.\"\"\"\nimport re\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES, IGNORED_PARTS\nfrom rung.evidence import find_file, read_text\n\n\ndef check_agent_policy(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Agent policy file\",\n        description=\"AGENTS.md or .github/copilot-instructions.md exists at repo root\",\n        weight=15, blocking=True,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.HIGH,\n        blocking_for=[\"local\", \"pr\", \"merge\", \"release\"],\n        source_mappings=[\n            {\"id\": \"agents_md\", \"classification\": SOURCES[\"agents_md\"][\"classification\"].value},\n            {\"id\": \"github_copilot\", \"classification\": SOURCES[\"github_copilot\"][\"classification\"].value},\n        ],\n    )\n    candidates = [\n        root / \"AGENTS.md\",\n        root / \".github\" / \"copilot-instructions.md\",\n        root / \"CLAUDE.md\",\n        root / \"GEMINI.md\",\n    ]\n    found = find_file(root, candidates)\n    found = [p for p in found if all(\n        re.search(pattern, read_text(p) or \"\", re.IGNORECASE | re.MULTILINE)\n        for pattern in (r\"^#{1,6}\\s+.*(?:build|test)\", r\"^#{1,6}\\s+.*security\")\n    )]\n    nested = list(root.rglob(\"AGENTS.md\"))\n    nested = [p for p in nested if p != root / \"AGENTS.md\" and all(part not in IGNORED_PARTS for part in p.relative_to(root).parts[:-1]) and p.is_file()]\n\n    if found:\n        r.state = EvidenceState.DETECTED\n        r.evidence.append(f\"Found: {found[0].relative_to(root)}\")\n        if len(found) > 1:\n            r.evidence.append(f\"Also found: {', '.join(str(p.relative_to(root)) for p in found[1:])}\")\n        if nested:\n            r.evidence.append(f\"Nested AGENTS.md files: {len(nested)} (good for monorepos)\")\n    else:\n        r.remediation = [\n            \"Create an AGENTS.md at the repo root with these sections:\",\n            \"  1. Project overview (what the project does)\",\n            \"  2. Build/test commands (exact commands agents should run)\",\n            \"  3. Code style conventions\",\n            \"  4. Testing instructions\",\n            \"  5. Security considerations (what agents must never do)\",\n            f\"See exemplars: {SOURCES['openai_codex']['url']}\",\n        ]\n    return r\n","rung.checks.build_commands":"\"\"\"Check 2: Build/test commands declared and runnable.\"\"\"\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import read_text, detect_build_commands\n\n\ndef check_build_commands(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Build & test commands\",\n        description=\"AGENTS.md declares concrete build/test commands that exist and run\",\n        weight=15, blocking=True,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.HIGH,\n        blocking_for=[\"local\", \"pr\", \"merge\"],\n        source_mappings=[\n            {\"id\": \"openai_codex\", \"classification\": SOURCES[\"openai_codex\"][\"classification\"].value},\n            {\"id\": \"github_copilot\", \"classification\": SOURCES[\"github_copilot\"][\"classification\"].value},\n        ],\n    )\n    agents_md = root / \"AGENTS.md\"\n    if not agents_md.exists():\n        r.remediation = [\"First create an AGENTS.md (see Check 1), then declare build/test commands in it.\"]\n        return r\n\n    content = read_text(agents_md) or \"\"\n    found_cmds = detect_build_commands(content)\n    found_cmds = [command for command in found_cmds if not (\n        command.startswith((\"python \", \"python3 \"))\n        and command.split()[-1].endswith(\".py\")\n        and not (root / command.split()[-1]).is_file()\n    )]\n\n    makefile = root / \"Makefile\"\n    justfile = root / \"justfile\"\n    package_json = root / \"package.json\"\n\n    has_runner = makefile.exists() or justfile.exists() or package_json.exists()\n    if found_cmds:\n        r.state = EvidenceState.DETECTED\n        r.evidence.append(f\"Declared commands: {', '.join(set(found_cmds[:5]))}\")\n        if has_runner:\n            r.evidence.append(\"Build runner found (Makefile/justfile/package.json)\")\n    elif has_runner:\n        r.state = EvidenceState.CLAIMED\n        r.evidence.append(\"Build runner found but not referenced in AGENTS.md\")\n        r.limitations.append(\"AGENTS.md should explicitly name the build/test commands agents must use\")\n        r.remediation = [\n            \"Add a 'Build & Test' section to AGENTS.md with the exact commands, e.g.:\",\n            \"  npm test     # run all tests\",\n            \"  npm run build  # build the project\",\n        ]\n    else:\n        r.remediation = [\n            \"Add a Makefile or justfile with 'test' and 'build' targets,\",\n            \"then reference them in AGENTS.md.\",\n        ]\n    return r\n","rung.checks.cyclic_verification":"\"\"\"Check 11: Cyclic verification loop (plan->build->verify->fix->verify).\"\"\"\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import read_text, has_affirmative_pattern\n\n\ndef check_cyclic_verification(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Cyclic verification\",\n        description=\"Workflow loops: plan -> build -> verify -> fix -> verify until pass\",\n        weight=5, blocking=False,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.MEDIUM,\n        source_mappings=[\n            {\"id\": \"anthropic_multiagent\", \"classification\": SOURCES[\"anthropic_multiagent\"][\"classification\"].value},\n        ],\n    )\n    patterns = [\n        r'(?:trycycle|try.cycle|verification.loop|fix.loop)',\n        r'(?:plan|build|verify|review|fix).*loop',\n        r'rerun.*verification',\n        r're-?verify',\n        r'(?:if.*fail|on.*fail).*fix.*(?:verify|test)',\n    ]\n    files_to_check = [root / \"AGENTS.md\", root / \"CONTRIBUTING.md\"]\n    found = False\n    for f in files_to_check:\n        if f.exists():\n            content = read_text(f)\n            if content is None:\n                continue\n            if has_affirmative_pattern(content, patterns):\n                found = True\n                r.evidence.append(f\"Cyclic verification in {f.relative_to(root)}\")\n    if found:\n        r.state = EvidenceState.DETECTED\n    else:\n        r.remediation = [\n            \"Document a cyclic verification loop in AGENTS.md:\",\n            \"  plan -> build -> verify -> (if fail) fix -> verify again -> review\",\n        ]\n    return r\n","rung.checks.evidence_traceability":"\"\"\"Check 5: Evidence and traceability for completed work.\n\nDoes not give credit merely because .github/workflows exists. CI\nworkflow existence alone is detected, not enforced or verified.\n\"\"\"\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import find_file, has_ci_workflows, ci_workflow_runs_tests\n\n\ndef check_evidence_traceability(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Evidence & traceability\",\n        description=\"Evidence index, traceability matrix, or CI artifacts linking work to verified outcomes\",\n        weight=10, blocking=False,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.MEDIUM,\n        source_mappings=[\n            {\"id\": \"ibm_adlc\", \"classification\": SOURCES[\"ibm_adlc\"][\"classification\"].value},\n            {\"id\": \"slsa\", \"classification\": SOURCES[\"slsa\"][\"classification\"].value},\n        ],\n    )\n    candidates = [\n        root / \"factory\" / \"evidence\" / \"index.json\",\n        root / \"docs\" / \"traceability-matrix.md\",\n        root / \"templates\" / \"traceability-matrix.md\",\n        root / \"evidence\",\n        root / \".evidence\",\n        root / \"test-results\",\n        root / \".test-results\",\n        root / \"CHANGELOG.md\",\n        root / \"docs\" / \"CHANGELOG.md\",\n    ]\n    found = find_file(root, candidates)\n    found = [p for p in found if p.is_dir() or (\n        len((text := p.read_text(encoding=\"utf-8\", errors=\"ignore\")).splitlines()) >= 3\n        and (\"changelog\" in text.lower() or \"trace\" in text.lower() or \"evidence\" in text.lower())\n    )]\n    ci_exists = has_ci_workflows(root)\n    ci_runs_tests = ci_workflow_runs_tests(root)\n\n    if ci_exists:\n        if ci_runs_tests:\n            r.evidence.append(\"CI workflows found that run tests\")\n        else:\n            r.evidence.append(\"CI workflow files found but do not appear to run tests\")\n            r.limitations.append(\"Workflow existence alone does not provide traceability; the workflow must produce test evidence\")\n\n    if found:\n        r.state = EvidenceState.DETECTED\n        if not any(\"CI workflows\" in d for d in r.evidence):\n            r.evidence.append(f\"Evidence system: {found[0].relative_to(root)}\")\n    else:\n        r.remediation = [\n            \"Create an evidence trail linking completed work to verification.\",\n            \"Options: a CHANGELOG.md, a factory/evidence/ index, CI workflow\",\n            \"artifacts, or a traceability matrix.\",\n        ]\n    return r\n","rung.checks.file_size":"\"\"\"Check 7: File-size discipline (non-scoring maintainability appendix).\n\nThis check has weight=0 and does NOT contribute to the governance score.\nIt appears in the report as a maintainability appendix. The 500/800 LoC\nthresholds come from openai/codex's AGENTS.md engineering convention, not\nan autonomous-agent governance standard.\n\"\"\"\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES, SOURCE_EXTENSIONS, IGNORED_PARTS, WATCH_LOC, SMELL_LOC, DEFECT_LOC\nfrom rung.evidence import count_source_loc, is_test_file\n\n\ndef check_file_size(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"File-size discipline\",\n        description=f\"Source files within size thresholds (warn>{WATCH_LOC} LoC, fail>{SMELL_LOC} LoC) \u2014 non-scoring maintainability appendix\",\n        weight=0, blocking=False,\n        state=EvidenceState.VERIFIED,\n        confidence=Confidence.HIGH,\n        source_mappings=[\n            {\"id\": \"openai_codex\", \"classification\": SOURCES[\"openai_codex\"][\"classification\"].value},\n        ],\n        limitations=[\n            \"File-size thresholds come from openai/codex's AGENTS.md engineering convention, not an autonomous-agent governance standard.\",\n            \"This check is non-scoring and appears only in the maintainability appendix.\",\n        ],\n    )\n    large_files = []\n    for path in root.rglob(\"*\"):\n        if not path.is_file():\n            continue\n        if any(part in IGNORED_PARTS for part in path.parts):\n            continue\n        if path.suffix not in SOURCE_EXTENSIONS:\n            continue\n        if is_test_file(path):\n            continue\n        loc = count_source_loc(path)\n        if loc >= DEFECT_LOC:\n            large_files.append((\"DEFECT\", path.relative_to(root), loc))\n        elif loc >= SMELL_LOC:\n            large_files.append((\"SMELL\", path.relative_to(root), loc))\n        elif loc >= WATCH_LOC:\n            large_files.append((\"WATCH\", path.relative_to(root), loc))\n\n    if not large_files:\n        r.evidence.append(\"All source files within thresholds\")\n    else:\n        r.state = EvidenceState.ABSENT\n        for level, rel, loc in large_files[:10]:\n            r.evidence.append(f\"[{level}] {rel} ({loc} LoC)\")\n        r.remediation = [\n            f\"Target: modules under {WATCH_LOC} LoC (excluding tests)\",\n            f\"Hard cap: files over {SMELL_LOC} LoC must add new functionality\",\n            \"in a new module unless there is a documented reason not to.\",\n            \"Consider splitting large files or adding an exemption comment.\",\n        ]\n    return r","rung.checks.independent_review":"\"\"\"Check 10: Independent review requirement.\"\"\"\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import read_text, has_affirmative_pattern\n\n\ndef check_independent_review(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Independent review\",\n        description=\"Documented requirement for independent review before commit\",\n        weight=5, blocking=False,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.MEDIUM,\n        source_mappings=[\n            {\"id\": \"anthropic_multiagent\", \"classification\": SOURCES[\"anthropic_multiagent\"][\"classification\"].value},\n            {\"id\": \"nist_rmf\", \"classification\": SOURCES[\"nist_rmf\"][\"classification\"].value},\n        ],\n    )\n    patterns = [\n        r'(?:independent|rubberduck|peer|code)\\s+review',\n        r'review\\s+(?:before|prior\\s+to)\\s+(?:commit|merge|push)',\n        r'self-review.*review',\n    ]\n    files_to_check = [root / \"AGENTS.md\", root / \"CONTRIBUTING.md\", root / \".github\" / \"pull_request_template.md\", root / \"REVIEW.md\"]\n    found = False\n    for f in files_to_check:\n        if f.exists():\n            content = read_text(f)\n            if content is None:\n                continue\n            if has_affirmative_pattern(content, patterns):\n                found = True\n                r.evidence.append(f\"Review requirement in {f.relative_to(root)}\")\n    if found:\n        r.state = EvidenceState.DETECTED\n    else:\n        r.remediation = [\n            \"Add an independent review requirement to AGENTS.md:\",\n            \"  'Before committing: complete self-review, then independent\",\n            \"  (rubberduck) review, then rerun verification, then commit.'\",\n        ]\n    return r\n","rung.checks.security_never_rules":"\"\"\"Check 9: Security 'Never' rules in agent policy.\"\"\"\nimport re\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import read_text\n\n\ndef check_security_never_rules(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Security Never-rules\",\n        description=\"AGENTS.md or SECURITY.md enumerates hard 'Never' rules for agents\",\n        weight=10, blocking=True,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.HIGH,\n        blocking_for=[\"local\", \"pr\", \"merge\", \"release\"],\n        source_mappings=[\n            {\"id\": \"nist_rmf\", \"classification\": SOURCES[\"nist_rmf\"][\"classification\"].value},\n            {\"id\": \"apache_airflow\", \"classification\": SOURCES[\"apache_airflow\"][\"classification\"].value},\n        ],\n    )\n    files_to_check = [root / \"AGENTS.md\", root / \"SECURITY.md\", root / \".github\" / \"SECURITY.md\"]\n    never_rules = set()\n    for f in files_to_check:\n        if f.exists():\n            content = read_text(f)\n            if content is None:\n                continue\n            never_rules.update(\n                re.sub(r'\\s+', ' ', line.strip().lower()) for line in content.splitlines()\n                if re.match(r'^\\s*(?:(?:[-*]|\\d+[.)])\\s+)?Never\\b', line, re.IGNORECASE)\n                and re.search(r'\\b(?:secret|credential|key|socket|git|security|policy|verification|commit|merge|release|destructive|transmit|execute|threshold|external)\\b', line, re.IGNORECASE)\n            )\n    never_count = len(never_rules)\n    if never_count >= 5:\n        r.state = EvidenceState.DETECTED\n        r.evidence.append(f\"Found {never_count} 'Never' rules across policy files\")\n    elif never_count >= 1:\n        r.state = EvidenceState.CLAIMED\n        r.evidence.append(f\"Found {never_count} 'Never' rule(s) \u2014 recommend at least 5\")\n        r.limitations.append(\"Consider adding more explicit 'Never' rules for security boundaries\")\n        r.remediation = [\n            \"Add more 'Never' rules to AGENTS.md or SECURITY.md, e.g.:\",\n            \"  Never commit secrets, API keys, or credentials\",\n            \"  Never expose the Docker socket to construction agents\",\n            \"  Never use destructive git operations without explicit request\",\n        ]\n    else:\n        r.remediation = [\n            \"Add a 'Never' rules section to AGENTS.md or SECURITY.md.\",\n        ]\n    return r\n","rung.checks.session_ledger":"\"\"\"Check 6: Session ledger / status tracking.\"\"\"\nimport json\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import find_file, has_valid_json\n\n\ndef check_session_ledger(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Session ledger\",\n        description=\"Machine-readable status file, work queue, or changelog for tracking agent sessions\",\n        weight=5, blocking=False,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.MEDIUM,\n        source_mappings=[\n            {\"id\": \"anthropic_multiagent\", \"classification\": SOURCES[\"anthropic_multiagent\"][\"classification\"].value},\n            {\"id\": \"ibm_adlc\", \"classification\": SOURCES[\"ibm_adlc\"][\"classification\"].value},\n        ],\n    )\n    candidates = [\n        root / \"factory\" / \"status.json\",\n        root / \"factory\" / \"queue.json\",\n        root / \"docs\" / \"sessions\" / \"current.md\",\n        root / \"sessions\" / \"current.md\",\n        root / \"SESSIONS.md\",\n        root / \".factory\" / \"sessions\" / \"current.md\",\n        root / \"STATUS.md\",\n        root / \"docs\" / \"STATUS.md\",\n        root / \"CHANGELOG.md\",\n    ]\n    found = find_file(root, candidates)\n    found = [p for p in found if p.suffix != \".json\" or (\n        has_valid_json(p)\n        and any(key in json.loads(p.read_text(encoding=\"utf-8\")) for key in (\"state\", \"status\", \"active_increment\", \"items\"))\n    )]\n    if found:\n        r.state = EvidenceState.DETECTED\n        r.evidence.append(f\"Session/status tracking: {found[0].relative_to(root)}\")\n    else:\n        r.remediation = [\n            \"Create a session ledger or status file (e.g., docs/sessions/current.md,\",\n            \"factory/status.json, or CHANGELOG.md) that records the active work\",\n            \"item, last update timestamp, and any blockers.\",\n        ]\n    return r\n","rung.checks.source_registry":"\"\"\"Check 4: Source-of-truth registry for external claims.\"\"\"\nimport json\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import find_file, has_valid_json\n\n\ndef check_source_registry(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Source-of-truth registry\",\n        description=\"Machine-readable source registry for external claims and references\",\n        weight=10, blocking=False,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.MEDIUM,\n        source_mappings=[\n            {\"id\": \"nist_rmf\", \"classification\": SOURCES[\"nist_rmf\"][\"classification\"].value},\n            {\"id\": \"ibm_adlc\", \"classification\": SOURCES[\"ibm_adlc\"][\"classification\"].value},\n        ],\n    )\n    candidates = [\n        root / \"docs\" / \"research\" / \"sources.json\",\n        root / \"docs\" / \"sources.json\",\n        root / \"SOURCES.md\",\n        root / \"docs\" / \"SOURCES.md\",\n    ]\n    found = find_file(root, candidates)\n    found = [p for p in found if p.suffix != \".json\" or (\n        has_valid_json(p)\n        and isinstance((data := json.loads(p.read_text(encoding=\"utf-8\"))).get(\"sources\"), list)\n        and bool(data[\"sources\"])\n    )]\n    if found:\n        r.state = EvidenceState.DETECTED\n        r.evidence.append(f\"Source registry: {found[0].relative_to(root)}\")\n    else:\n        r.remediation = [\n            \"Create a source registry (e.g., docs/research/sources.json) that\",\n            \"records every external source cited in the repo with a SRC-ID,\",\n            \"URL, and classification (first_party / preprint / standard).\",\n        ]\n    return r\n","rung.checks.verification_gate":"\"\"\"Check 3: Verification gate before commit/merge.\n\nDoes not give credit merely for finding any .github/workflows file.\nWorkflow existence is detected at most; enforcement requires semantic\ninspection or is unobservable from public evidence.\n\"\"\"\nfrom pathlib import Path\nfrom rung.models import CheckResult, EvidenceState, Confidence\nfrom rung.sources import SOURCES\nfrom rung.evidence import read_text, has_affirmative_pattern, has_ci_workflows, ci_workflow_runs_tests, ci_workflow_enforces_gate\n\n\ndef check_verification_gate(root: Path) -> CheckResult:\n    r = CheckResult(\n        name=\"Verification gate\",\n        description=\"Documented rule that verification must pass before commit or merge\",\n        weight=10, blocking=True,\n        state=EvidenceState.ABSENT,\n        confidence=Confidence.MEDIUM,\n        blocking_for=[\"merge\", \"release\"],\n        source_mappings=[\n            {\"id\": \"nist_rmf\", \"classification\": SOURCES[\"nist_rmf\"][\"classification\"].value},\n            {\"id\": \"anthropic_multiagent\", \"classification\": SOURCES[\"anthropic_multiagent\"][\"classification\"].value},\n        ],\n    )\n    patterns = [\n        r'(?:before|prior\\s+to)\\s+(?:commit|push|merge|marking.*complete)',\n        r'verification?\\s+must\\s+pass',\n        r'(?:never|do\\s+not)\\s+(?:commit|push|merge)\\s+(?:without|until|before)',\n        r'(?:githook|pre-commit|husky)',\n    ]\n    files_to_check = [root / \"AGENTS.md\", root / \".github\" / \"pull_request_template.md\", root / \"CONTRIBUTING.md\"]\n    documented = False\n    for f in files_to_check:\n        if f.exists():\n            content = read_text(f)\n            if content is None:\n                continue\n            if has_affirmative_pattern(content, patterns):\n                documented = True\n                r.evidence.append(f\"Verification gate mentioned in {f.relative_to(root)}\")\n\n    githooks = root / \".githooks\"\n    husky = root / \".husky\"\n    has_hooks = any(path.is_dir() and any(child.is_file() for child in path.iterdir()) for path in (githooks, husky))\n    if has_hooks:\n        documented = True\n        r.evidence.append(\"Git hooks directory found (.githooks or .husky)\")\n\n    ci_exists = has_ci_workflows(root)\n    ci_runs_tests = ci_workflow_runs_tests(root)\n    ci_enforces = ci_workflow_enforces_gate(root)\n\n    if ci_exists:\n        if ci_enforces:\n            r.evidence.append(\"CI workflow references enforcement settings\")\n        elif ci_runs_tests:\n            r.evidence.append(\"CI workflow detected running tests (not necessarily enforced)\")\n        else:\n            r.evidence.append(\"CI workflow file found but does not appear to run tests\")\n            r.limitations.append(\"Workflow existence alone is not enforcement; the workflow must run tests and be required\")\n\n    if documented and ci_runs_tests:\n        r.state = EvidenceState.UNOBSERVABLE\n        r.limitations.append(\"Actual enforcement (required status checks, branch protection) is not observable from public repository contents without Administration read permission\")\n    elif documented or has_hooks:\n        r.state = EvidenceState.CLAIMED\n        r.limitations.append(\"Verification gate is documented but not confirmed as enforced by CI\")\n    elif ci_exists and not ci_runs_tests:\n        r.state = EvidenceState.CLAIMED\n        r.limitations.append(\"CI exists but does not run tests; this is not a verification gate\")\n    else:\n        r.remediation = [\n            \"Add an explicit rule to AGENTS.md or CONTRIBUTING.md:\",\n            \"  'Never commit or merge before verification (npm test) passes.'\",\n            \"Set up a pre-commit hook or CI gate that runs the test suite.\",\n        ]\n    return r\n","rung.cli":"#!/usr/bin/env python3\n\"\"\"Rung CLI \u2014 AI Agent Governance Audit\n\nScores a repository's readiness for AI coding agent governance using 11\nweighted checks derived from published standards and industry best practices.\n\nOutputs a numeric score (0-100), a letter grade (A-E), a quality gate\nverdict (PASS/FAIL), evidence states, and actionable next steps for each gap.\n\nUsage:\n    python3 -m rung.cli [--root /path/to/your/repo] [--json]\n\nExit codes:\n    0 \u2014 quality gate passed (all blocking checks passed)\n    1 \u2014 quality gate failed (one or more blocking checks failed)\n\nLicense: MIT\n\"\"\"\n\nfrom __future__ import annotations\n\nimport argparse\nimport json\nimport re\nimport sys\nfrom pathlib import Path\n\nfrom rung.audit import run_audit, result_to_dict\nfrom rung.scoring import GRADE_LABELS\n\n\ndef format_report(result) -> str:\n    \"\"\"Format a human-readable text report from AuditResult.\"\"\"\n    lines = []\n    lines.append(\"=\" * 60)\n    lines.append(\"  Rung \u2014 AI Agent Governance Audit\")\n    lines.append(\"=\" * 60)\n    lines.append(f\"  Repository: {result.repository}\")\n    if result.commit_sha:\n        lines.append(f\"  Commit: {result.commit_sha}\")\n    lines.append(f\"  Score: {result.score}/100  Grade: {result.grade} ({result.grade_label})\")\n    lines.append(f\"  Quality Gate: {result.quality_gate}\")\n    lines.append(f\"  Authority: {result.authority.value if hasattr(result.authority, 'value') else result.authority}\")\n    lines.append(f\"  Rung version: {result.rung_version}  Schema: {result.schema_version}\")\n    lines.append(f\"  Timestamp: {result.timestamp}\")\n    lines.append(f\"  Report digest: {result.report_data_sha256}\")\n    lines.append(\"=\" * 60)\n    lines.append(\"\")\n\n    for c in result.checks:\n        status = c.state.value if hasattr(c.state, \"value\") else str(c.state)\n        blocking_tag = \" [blocking]\" if c.blocking else \"\"\n        weight_tag = f\" ({c.weight} pts)\" if c.weight > 0 else \" (non-scoring)\"\n        lines.append(f\"  [{status.upper()}] {c.name}{weight_tag}{blocking_tag}\")\n        lines.append(f\"         {c.description}\")\n        for e in c.evidence:\n            lines.append(f\"         -> {e}\")\n        for lim in c.limitations:\n            lines.append(f\"         ! {lim}\")\n        if c.source_mappings:\n            src_ids = [sm[\"id\"] for sm in c.source_mappings]\n            lines.append(f\"         Sources: {', '.join(src_ids)}\")\n        if not c.passed and c.remediation:\n            lines.append(\"         Remediation:\")\n            for step in c.remediation:\n                lines.append(f\"           {step}\")\n        lines.append(\"\")\n\n    lines.append(\"-\" * 60)\n    lines.append(f\"  Score: {result.score}/100  Grade: {result.grade} ({result.grade_label})\")\n    lines.append(f\"  Quality Gate: {result.quality_gate}\")\n    lines.append(f\"  Authority: {result.authority.value if hasattr(result.authority, 'value') else result.authority}\")\n    failed_blocking = [c for c in result.checks if c.blocking and not c.passed]\n    if failed_blocking:\n        lines.append(f\"  Blocking failures: {len(failed_blocking)}\")\n        for c in failed_blocking:\n            lines.append(f\"    - {c.name} [{c.state.value if hasattr(c.state, 'value') else c.state}]\")\n    lines.append(\"\")\n    return \"\\n\".join(lines)\n\n\ndef main() -> int:\n    parser = argparse.ArgumentParser(description=\"Rung CLI \u2014 AI Agent Governance Audit\")\n    parser.add_argument(\"--root\", default=\".\", help=\"Repository root to audit\")\n    parser.add_argument(\"--commit-sha\", type=lambda value: value if re.fullmatch(r\"[0-9a-f]{40}\", value) else parser.error(\"--commit-sha must be 40 lowercase hex characters\"), help=\"Exact audited commit SHA\")\n    parser.add_argument(\"--repository\", help=\"Stable repository identifier for the result digest\")\n    parser.add_argument(\"--timestamp\", help=\"Explicit RFC 3339 report timestamp for deterministic rendering\")\n    parser.add_argument(\"--json\", action=\"store_true\", help=\"Output JSON instead of text\")\n    parser.add_argument(\"--preview\", action=\"store_true\", help=\"Output free preview JSON\")\n    parser.add_argument(\"--html\", action=\"store_true\", help=\"Output full HTML report\")\n    parser.add_argument(\"--pdf\", action=\"store_true\", help=\"Output PDF (requires weasyprint)\")\n    parser.add_argument(\"-o\", \"--output\", help=\"Write output to file instead of stdout\")\n    args = parser.parse_args()\n\n    root = Path(args.root).resolve()\n    result = run_audit(root, commit_sha=args.commit_sha, repository=args.repository, timestamp=args.timestamp)\n\n    if args.preview:\n        from rung.renderer import render_preview\n        output = json.dumps(render_preview(result), indent=2)\n    elif args.html:\n        from rung.renderer import render_html\n        output = render_html(result)\n    elif args.pdf:\n        from rung.renderer import render_pdf_data\n        pdf_bytes = render_pdf_data(result)\n        if args.output:\n            Path(args.output).write_bytes(pdf_bytes)\n            return 0 if result.quality_gate == \"PASS\" else 1\n        else:\n            sys.stdout.buffer.write(pdf_bytes)\n            return 0 if result.quality_gate == \"PASS\" else 1\n    elif args.json:\n        output = json.dumps(result_to_dict(result), indent=2)\n    else:\n        output = format_report(result)\n\n    if args.output:\n        Path(args.output).write_text(output, encoding=\"utf-8\")\n    else:\n        print(output)\n\n    return 0 if result.quality_gate == \"PASS\" else 1\n\n\nif __name__ == \"__main__\":\n    sys.exit(main())\n","rung.evidence":"\"\"\"Evidence collection helpers for Rung checks.\n\nProvides utilities for reading files, searching for patterns, and\ndetecting CI workflow semantics without giving false credit for\nworkflow existence alone.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport re\nimport json\nfrom pathlib import Path\nfrom typing import Optional\n\nfrom rung.sources import IGNORED_PARTS\n\n\ndef read_text(path: Path) -> Optional[str]:\n    \"\"\"Read a file as UTF-8 text, returning None on failure.\"\"\"\n    try:\n        return path.read_text(encoding=\"utf-8\", errors=\"ignore\")\n    except Exception:\n        return None\n\n\ndef find_file(root: Path, candidates: list[Path]) -> list[Path]:\n    \"\"\"Return existing files from a list of candidate paths.\"\"\"\n    return [p for p in candidates if p.is_file() and bool((read_text(p) or \"\").strip())]\n\n\ndef has_valid_json(path: Path) -> bool:\n    \"\"\"Return true for a nonempty regular file containing JSON data.\"\"\"\n    if not path.is_file():\n        return False\n    try:\n        value = json.loads(path.read_text(encoding=\"utf-8\"))\n        return isinstance(value, (dict, list)) and bool(value)\n    except (OSError, UnicodeError, json.JSONDecodeError):\n        return False\n\n\ndef has_affirmative_pattern(content: str, patterns: list[str]) -> bool:\n    \"\"\"Match policy language while rejecting obvious negations and examples.\"\"\"\n    for line in content.splitlines():\n        normalized = line.strip().lower()\n        if not normalized or normalized.startswith((\"# example\", \"example:\")):\n            continue\n        if re.search(r\"\\b(?:do not|don't|not required|never use|must not|optional|convenient)\\b\", normalized):\n            continue\n        if any(has_pattern(line, pattern) for pattern in patterns):\n            return True\n    return False\n\n\ndef count_pattern(content: str, pattern: str) -> int:\n    \"\"\"Count regex matches in content (case-insensitive).\"\"\"\n    return len(re.findall(pattern, content, re.IGNORECASE))\n\n\ndef has_pattern(content: str, pattern: str) -> bool:\n    \"\"\"Check if content matches a regex pattern (case-insensitive).\"\"\"\n    return bool(re.search(pattern, content, re.IGNORECASE))\n\n\ndef has_ci_workflows(root: Path) -> bool:\n    \"\"\"Check if .github/workflows directory exists and has .yml/.yaml files.\"\"\"\n    ci_dir = root / \".github\" / \"workflows\"\n    if not ci_dir.exists():\n        return False\n    return bool(list(ci_dir.glob(\"*.yml\")) or list(ci_dir.glob(\"*.yaml\")))\n\n\ndef ci_workflow_runs_tests(root: Path) -> bool:\n    \"\"\"Semantic inspection: do CI workflows actually run tests?\n\n    Reads workflow YAML files and checks for test-related step content.\n    Finding any .github/workflows/*.yml does NOT automatically give credit.\n    The workflow must contain test-related commands.\n    \"\"\"\n    ci_dir = root / \".github\" / \"workflows\"\n    if not ci_dir.exists():\n        return False\n    test_patterns = [\n        r\"(?:npm|yarn|pnpm)\\s+(?:test|run\\s+test)\",\n        r\"(?:make|just)\\s+test\",\n        r\"(?:go|cargo)\\s+test\",\n        r\"python3?\\s+(?:-m\\s+)?pytest\",\n        r\"python3?\\s+\\S+\\.py.*test\",\n        r\"\\bpytest\\b\",\n        r\"\\bunittest\\b\",\n        r\"\\bjest\\b\",\n        r\"\\bvitest\\b\",\n    ]\n    for wf_file in list(ci_dir.glob(\"*.yml\")) + list(ci_dir.glob(\"*.yaml\")):\n        content = read_text(wf_file)\n        if content is None:\n            continue\n        lines = content.splitlines()\n        commands = []\n        index = 0\n        while index < len(lines):\n            command = re.match(r\"^(\\s*)(?:-\\s*)?run:\\s*(.*)$\", lines[index])\n            if not command:\n                index += 1\n                continue\n            value = command.group(2).strip()\n            if value in (\"|\", \">\", \"\"):\n                base_indent = len(command.group(1))\n                block = []\n                index += 1\n                while index < len(lines) and len(lines[index]) - len(lines[index].lstrip()) > base_indent:\n                    block.append(lines[index].strip())\n                    index += 1\n                commands.extend(block)\n                continue\n            commands.append(value)\n            index += 1\n        for command in commands:\n            if re.match(r\"^(?:echo|printf)\\b\", command):\n                continue\n            if any(has_pattern(command, pattern) for pattern in test_patterns):\n                return True\n    return False\n\n\ndef ci_workflow_enforces_gate(root: Path) -> bool:\n    \"\"\"Semantic inspection: does CI enforce required status checks?\n\n    Reads workflow YAML for branch protection hints. Note: actual branch\n    protection rules are not observable from public repository contents\n    without Administration read permission. This function only checks\n    whether workflows reference required status checks or protection\n    language. It does NOT claim enforcement.\n    \"\"\"\n    ci_dir = root / \".github\" / \"workflows\"\n    if not ci_dir.exists():\n        return False\n    enforcement_patterns = [\n        r\"required_status_checks\",\n        r\"branch_protection\",\n        r\"enforce_admins\",\n        r\"required_pull_request_reviews\",\n    ]\n    for wf_file in list(ci_dir.glob(\"*.yml\")) + list(ci_dir.glob(\"*.yaml\")):\n        content = read_text(wf_file)\n        if content is None:\n            continue\n        for pattern in enforcement_patterns:\n            if has_pattern(content, pattern):\n                return True\n    return False\n\n\ndef detect_build_commands(content: str) -> list[str]:\n    \"\"\"Detect build/test commands in AGENTS.md or similar file content.\n\n    Recognizes python3 (not just python), python -m, shell scripts, make,\n    just, and package-manager commands.\n    \"\"\"\n    cmd_patterns = [\n        r'(?:npm|yarn|pnpm)\\s+(?:test|run\\s+test|run\\s+build)',\n        r'(?:make|just)\\s+(?:test|build|verify|all)',\n        r'(?:go|cargo|rustc)\\s+(?:test|build)',\n        r'python3\\s+(?:-m\\s+)?(?:pytest|unittest)',\n        r'python3\\s+\\S+\\.py',\n        r'python\\s+(?:-m\\s+)?(?:pytest|unittest)',\n        r'python\\s+\\S+\\.py',\n        r'\\./\\S+\\s+(?:test|build|verify)',\n        r'ruby\\s+(?:-I\\S+\\s+)?\\S+test\\S*',\n        r'dotnet\\s+(?:test|build)',\n    ]\n    found = []\n    for line in content.splitlines():\n        if re.search(r\"\\b(?:do not|don't|never|must not)\\b\", line, re.IGNORECASE):\n            continue\n        for pattern in cmd_patterns:\n            found.extend(re.findall(pattern, line))\n    return sorted(set(found))\n\n\ndef count_source_loc(path: Path) -> int:\n    \"\"\"Count lines of code in a source file, excluding tests.\"\"\"\n    try:\n        with path.open(encoding=\"utf-8\", errors=\"ignore\") as source:\n            return sum(1 for _ in source)\n    except Exception:\n        return 0\n\n\ndef is_test_file(path: Path) -> bool:\n    \"\"\"Check if a path is a test file by name conventions.\"\"\"\n    name = path.name.lower()\n    stem = path.stem.lower()\n    return (\n        name.startswith(\"test_\")\n        or stem.endswith(\"_test\")\n        or \"tests\" in path.parts\n        or \".test.\" in name\n        or name.endswith(\".test.ts\")\n        or name.endswith(\".test.js\")\n        or name.endswith(\".spec.ts\")\n        or name.endswith(\".spec.js\")\n    )\n","rung.models":"\"\"\"Core data models for the Rung audit engine.\n\nDefines evidence states, confidence levels, source classifications,\nauthority recommendations, and the CheckResult dataclass that every\ncheck returns. Replaces the boolean-only pass/fail model with a\nsix-state evidence maturity model.\n\"\"\"\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass, field\nfrom enum import Enum\nfrom typing import Optional\n\n\nclass EvidenceState(str, Enum):\n    \"\"\"Six-state evidence maturity model replacing boolean pass/fail.\"\"\"\n    ABSENT = \"absent\"\n    CLAIMED = \"claimed\"\n    DETECTED = \"detected\"\n    ENFORCED = \"enforced\"\n    VERIFIED = \"verified\"\n    UNOBSERVABLE = \"unobservable\"\n\n\nclass Confidence(str, Enum):\n    \"\"\"Per-finding confidence level.\"\"\"\n    LOW = \"low\"\n    MEDIUM = \"medium\"\n    HIGH = \"high\"\n\n\nclass SourceClass(str, Enum):\n    \"\"\"Source authority classification.\"\"\"\n    STANDARD = \"standard\"\n    PLATFORM_CONTROL = \"platform_control\"\n    VENDOR_GUIDANCE = \"vendor_guidance\"\n    INDUSTRY_PRACTICE = \"industry_practice\"\n    EXEMPLAR = \"exemplar\"\n    EDOWORKS_POLICY = \"edoworks_policy\"\n\n\nclass AuthorityLevel(str, Enum):\n    \"\"\"Maximum recommended agent authority based on public evidence.\n\n    A public-only report must never recommend autonomous merge or release\n    when enforcement settings are unobservable.\n    \"\"\"\n    UNSAFE = \"unsafe\"\n    LOCAL_ONLY = \"local_only\"\n    PR_ONLY_PROVISIONAL = \"pr_only_provisional\"\n    OWNER_EVIDENCE_REQUIRED = \"owner_evidence_required\"\n\n\n@dataclass\nclass CheckResult:\n    \"\"\"Result of a single governance check.\n\n    Replaces the boolean-only model. Every check returns an evidence state,\n    confidence, blocking authority, evidence snippets, limitations,\n    remediation steps, and source mappings.\n    \"\"\"\n    name: str\n    description: str\n    weight: int\n    blocking: bool\n    state: EvidenceState\n    confidence: Confidence = Confidence.MEDIUM\n    blocking_for: list[str] = field(default_factory=list)\n    evidence: list[str] = field(default_factory=list)\n    limitations: list[str] = field(default_factory=list)\n    remediation: list[str] = field(default_factory=list)\n    source_mappings: list[dict] = field(default_factory=list)\n\n    @property\n    def passed(self) -> bool:\n        \"\"\"Backward compatibility: a check 'passes' if its state is\n        detected, enforced, or verified. Absent, claimed, and unobservable\n        do not pass. Blocking checks must pass for the quality gate.\"\"\"\n        return self.state in (\n            EvidenceState.DETECTED,\n            EvidenceState.ENFORCED,\n            EvidenceState.VERIFIED,\n        )\n\n\n@dataclass\nclass AuditResult:\n    \"\"\"Canonical immutable audit result (AuditResult v1).\n\n    The free preview and paid PDF both render from this same object.\n    Includes a report-data digest field that is computed over the\n    canonical JSON of all other fields (excluding the digest itself).\n    \"\"\"\n    repository: str\n    commit_sha: Optional[str]\n    checks: list[CheckResult]\n    score: int\n    grade: str\n    grade_label: str\n    quality_gate: str\n    authority: AuthorityLevel\n    rung_version: str\n    schema_version: str\n    timestamp: str\n    report_data_sha256: Optional[str] = None","rung.renderer":"\"\"\"Report renderer \u2014 projects AuditResult v1 into preview and PDF formats.\n\nBoth the free preview and the paid PDF render from the same immutable\nAuditResult. The preview is a JSON subset; the PDF is an HTML document\nthat can be printed to PDF by a headless browser or weasyprint.\n\nThe renderer is deterministic: given the same AuditResult, it produces\nthe same output. No timestamps are added beyond what's in the result.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nfrom typing import Optional\nfrom html import escape\n\nfrom rung.models import AuditResult, CheckResult, EvidenceState, AuthorityLevel\nfrom rung.audit import result_to_dict\n\n\ndef render_preview(result: AuditResult) -> dict:\n    \"\"\"Render the free preview from AuditResult v1.\n\n    Returns only: canonical repository name, exact commit SHA,\n    provisional score, authority recommendation, top two findings,\n    one recommended action, locked finding count, and opaque audit ticket.\n    The ticket is a placeholder \u2014 the service layer fills it in.\n    \"\"\"\n    checks_sorted = sorted(result.checks, key=lambda c: (not c.blocking, c.name))\n    top_two = []\n    for c in checks_sorted:\n        if not c.passed:\n            top_two.append({\n                \"name\": c.name,\n                \"state\": c.state.value if hasattr(c.state, \"value\") else str(c.state),\n                \"description\": c.description,\n            })\n        if len(top_two) >= 2:\n            break\n\n    one_remediation = \"\"\n    for c in checks_sorted:\n        if not c.passed and c.remediation:\n            one_remediation = c.remediation[0]\n            break\n\n    locked_count = sum(1 for c in result.checks if not c.passed) - len(top_two)\n\n    return {\n        \"repository\": result.repository,\n        \"commit_sha\": result.commit_sha,\n        \"score\": result.score,\n        \"grade\": result.grade,\n        \"grade_label\": result.grade_label,\n        \"quality_gate\": result.quality_gate,\n        \"authority\": result.authority.value if hasattr(result.authority, \"value\") else str(result.authority),\n        \"top_two_findings\": top_two,\n        \"recommended_action\": one_remediation,\n        \"locked_finding_count\": max(locked_count, 0),\n        \"audit_ticket\": None,\n    }\n\n\ndef render_html(result: AuditResult) -> str:\n    \"\"\"Render the full HTML report from AuditResult v1.\n\n    This HTML can be printed to PDF by a headless browser or weasyprint.\n    The output is deterministic for the same AuditResult.\n    \"\"\"\n    r = result\n    authority_val = r.authority.value if hasattr(r.authority, \"value\") else str(r.authority)\n\n    sections = []\n\n    # Cover\n    sections.append(f\"\"\"<section class=\"cover\">\n  <h1>Rung Public-Evidence Audit Report</h1>\n  <p class=\"repo\">{escape(r.repository)}</p>\n  {f'<p class=\"commit\">Commit: <code>{escape(r.commit_sha)}</code></p>' if r.commit_sha else ''}\n  <p class=\"meta\">Rung {escape(r.rung_version)} \u00b7 Schema {escape(r.schema_version)} \u00b7 {escape(r.timestamp)}</p>\n</section>\"\"\")\n\n    # Executive verdict\n    sections.append(f\"\"\"<section class=\"verdict\">\n  <h2>Executive Verdict</h2>\n  <table class=\"verdict-table\">\n    <tr><th>Score</th><td>{r.score}/100</td></tr>\n    <tr><th>Grade</th><td>{escape(r.grade)} \u2014 {escape(r.grade_label)}</td></tr>\n    <tr><th>Quality Gate</th><td class=\"{'pass' if r.quality_gate == 'PASS' else 'fail'}\">{r.quality_gate}</td></tr>\n    <tr><th>Recommended Authority</th><td>{escape(authority_val.replace(\"_\", \" \").title())}</td></tr>\n  </table>\n</section>\"\"\")\n\n    # Public-evidence matrix\n    rows = []\n    for c in r.checks:\n        state_val = c.state.value if hasattr(c.state, \"value\") else str(c.state)\n        conf_val = c.confidence.value if hasattr(c.confidence, \"value\") else str(c.confidence)\n        state_class = state_val\n        weight_str = f\"{c.weight} pts\" if c.weight > 0 else \"non-scoring\"\n        blocking_str = \"blocking\" if c.blocking else \"\"\n        evidence_html = \"<br>\".join(f\"&rarr; {escape(e)}\" for e in c.evidence) if c.evidence else \"<em>none</em>\"\n        limitations_html = \"<br>\".join(f\"&#9888; {escape(l)}\" for l in c.limitations) if c.limitations else \"\"\n        remediation_html = \"<br>\".join(f\"{escape(s)}\" for s in c.remediation) if c.remediation else \"\"\n        sources_html = \", \".join(escape(sm[\"id\"]) for sm in c.source_mappings) if c.source_mappings else \"\"\n\n        rows.append(f\"\"\"<tr class=\"{state_class}\">\n  <td class=\"state\">{escape(state_val.upper())}</td>\n  <td>{escape(c.name)} <span class=\"weight\">({weight_str})</span> {f'<span class=\"blocking\">{blocking_str}</span>' if blocking_str else ''}</td>\n  <td>{escape(conf_val)}</td>\n  <td>{evidence_html}</td>\n  <td>{limitations_html}</td>\n  <td>{remediation_html}</td>\n  <td>{sources_html}</td>\n</tr>\"\"\")\n\n    sections.append(f\"\"\"<section class=\"matrix\">\n  <h2>Public-Evidence Matrix</h2>\n  <table class=\"matrix-table\">\n    <thead>\n      <tr><th>State</th><th>Check</th><th>Confidence</th><th>Evidence</th><th>Limitations</th><th>Remediation</th><th>Sources</th></tr>\n    </thead>\n    <tbody>\n      {''.join(rows)}\n    </tbody>\n  </table>\n</section>\"\"\")\n\n    # Critical and high-priority findings\n    failed_blocking = [c for c in r.checks if c.blocking and not c.passed]\n    if failed_blocking:\n        findings_items = []\n        for c in failed_blocking:\n            state_val = c.state.value if hasattr(c.state, \"value\") else str(c.state)\n            findings_items.append(f\"\"\"<li><strong>{escape(c.name)}</strong> [{escape(state_val)}]: {escape(c.description)}<br>\n        {'<br>'.join(escape(s) for s in c.remediation)}</li>\"\"\")\n        sections.append(f\"\"\"<section class=\"findings\">\n  <h2>Critical and High-Priority Findings</h2>\n  <ul class=\"findings-list\">\n    {''.join(findings_items)}\n  </ul>\n</section>\"\"\")\n\n    # Full remediation sequence\n    all_remediation = [(c.name, c.remediation) for c in r.checks if not c.passed and c.remediation]\n    if all_remediation:\n        remediation_steps = []\n        step_num = 1\n        for name, steps in all_remediation:\n            for step in steps:\n                remediation_steps.append(f\"<li>{escape(step)} <em>({escape(name)})</em></li>\")\n                step_num += 1\n        sections.append(f\"\"\"<section class=\"remediation\">\n  <h2>Full Remediation Sequence</h2>\n  <ol class=\"remediation-list\">\n    {''.join(remediation_steps)}\n  </ol>\n</section>\"\"\")\n\n    # Source mapping\n    all_sources = set()\n    for c in r.checks:\n        for sm in c.source_mappings:\n            all_sources.add(sm[\"id\"])\n    if all_sources:\n        from rung.sources import SOURCES\n        source_lines = []\n        for sid in sorted(all_sources):\n            if sid in SOURCES:\n                s = SOURCES[sid]\n                source_lines.append(f\"<li><strong>{escape(sid)}</strong>: {escape(s['name'])} \u2014 <a href=\\\"{escape(s['url'])}\\\">{escape(s['url'])}</a></li>\")\n        sections.append(f\"\"\"<section class=\"sources\">\n  <h2>Source Mapping</h2>\n  <ul class=\"source-list\">\n    {''.join(source_lines)}\n  </ul>\n</section>\"\"\")\n\n    # Limitations and unobservable controls\n    unobservable = [c for c in r.checks if hasattr(c.state, \"value\") and c.state.value == \"unobservable\"]\n    all_limitations = []\n    for c in r.checks:\n        for lim in c.limitations:\n            all_limitations.append(f\"<li>{escape(lim)} <em>({escape(c.name)})</em></li>\")\n    if unobservable:\n        for c in unobservable:\n            all_limitations.append(f\"<li>{escape(c.name)}: control is not observable from public evidence</li>\")\n    if all_limitations:\n        sections.append(f\"\"\"<section class=\"limitations\">\n  <h2>Limitations and Unobservable Controls</h2>\n  <ul class=\"limitations-list\">\n    {''.join(all_limitations)}\n  </ul>\n</section>\"\"\")\n\n    # Methodology and report digest\n    sections.append(f\"\"\"<section class=\"methodology\">\n  <h2>Methodology and Report Digest</h2>\n  <p>This report is an automated public-evidence assessment. It is informed by\n  standards and industry practices (NIST AI RMF, SLSA, OpenSSF Scorecard). It is\n  not certification, compliance, or legal advice.</p>\n  <p>A public, accountless scan cannot inspect some important enforcement settings.\n  GitHub's branch-protection API requires Administration read permission, even for\n  reads on public repositories. Rung labels these controls as <strong>unobservable</strong>\n  rather than passing or failing them.</p>\n  <table class=\"digest-table\">\n    <tr><th>Repository</th><td><code>{escape(r.repository)}</code></td></tr>\n    {f'<tr><th>Commit SHA</th><td><code>{escape(r.commit_sha)}</code></td></tr>' if r.commit_sha else ''}\n    <tr><th>Rung version</th><td>{escape(r.rung_version)}</td></tr>\n    <tr><th>Schema version</th><td>{escape(r.schema_version)}</td></tr>\n    <tr><th>Timestamp</th><td>{escape(r.timestamp)}</td></tr>\n    <tr><th>Report-data SHA-256</th><td><code>{escape(r.report_data_sha256 or \"\")}</code></td></tr>\n  </table>\n</section>\"\"\")\n\n    html = f\"\"\"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <title>Rung Public-Evidence Audit Report \u2014 {escape(r.repository)}</title>\n  <style>\n    body {{ font-family: -apple-system, BlinkMacSystemFont, \"Segoe UI\", sans-serif; line-height: 1.55; color: #1f2937; max-width: 900px; margin: 0 auto; padding: 40px; }}\n    h1 {{ font-size: 1.8rem; border-bottom: 2px solid #7c3aed; padding-bottom: 8px; }}\n    h2 {{ font-size: 1.3rem; margin-top: 32px; border-bottom: 1px solid #e5e7eb; padding-bottom: 4px; }}\n    table {{ width: 100%; border-collapse: collapse; margin: 12px 0; font-size: 0.9rem; }}\n    th {{ text-align: left; padding: 6px 8px; background: #f9fafb; border: 1px solid #e5e7eb; }}\n    td {{ padding: 6px 8px; border: 1px solid #e5e7eb; vertical-align: top; }}\n    .cover h1 {{ border: none; }}\n    .repo {{ font-size: 1.1rem; color: #6b7280; }}\n    .commit {{ font-size: 0.85rem; color: #6b7280; }}\n    .meta {{ font-size: 0.8rem; color: #9ca3af; }}\n    .verdict-table th {{ width: 200px; }}\n    .pass {{ color: #059669; font-weight: bold; }}\n    .fail {{ color: #dc2626; font-weight: bold; }}\n    .matrix-table td {{ font-size: 0.82rem; }}\n    .state {{ font-weight: bold; white-space: nowrap; }}\n    .detected {{ color: #059669; }}\n    .claimed {{ color: #d97706; }}\n    .absent {{ color: #dc2626; }}\n    .unobservable {{ color: #6366f1; }}\n    .verified {{ color: #059669; }}\n    .enforced {{ color: #059669; }}\n    .weight {{ font-size: 0.78rem; color: #9ca3af; }}\n    .blocking {{ font-size: 0.7rem; background: #fee2e2; color: #991b1b; padding: 1px 4px; border-radius: 3px; }}\n    .findings-list li, .remediation-list li, .limitations-list li {{ margin-bottom: 8px; }}\n    .source-list li {{ font-size: 0.85rem; }}\n    .digest-table th {{ width: 180px; }}\n    code {{ background: #f3f4f6; padding: 1px 4px; border-radius: 3px; font-size: 0.85em; }}\n    a {{ color: #7c3aed; }}\n    @media print {{ body {{ max-width: none; padding: 0; }} }}\n  </style>\n</head>\n<body>\n  {''.join(sections)}\n</body>\n</html>\"\"\"\n    return html\n\n\ndef render_pdf_data(result: AuditResult) -> bytes:\n    \"\"\"Render PDF bytes from AuditResult v1.\n\n    Uses the HTML renderer and converts to PDF. The conversion method\n    depends on what's available: weasyprint if installed, otherwise\n    raises NotImplementedError with guidance.\n\n    In the private report service, this will be called with a headless\n    browser or weasyprint. The factory's production path must be\n    deterministic and invoke no LLM.\n    \"\"\"\n    html = render_html(result)\n    try:\n        from weasyprint import HTML as WeasyprintHTML\n        pdf_bytes = WeasyprintHTML(string=html).write_pdf()\n        return pdf_bytes\n    except ImportError:\n        raise NotImplementedError(\n            \"weasyprint is not installed. Install it with: pip install weasyprint\\n\"\n            \"Alternatively, use render_html() and print to PDF via a headless browser.\"\n        )","rung.scoring":"\"\"\"Scoring and authority recommendation engine.\n\nComputes a numeric score (0-100), letter grade (A-E), quality gate\nverdict, and maximum recommended agent authority from check results.\nFile-size discipline is excluded from the governance score and appears\nonly in a non-scoring maintainability appendix.\n\"\"\"\n\nfrom rung.models import CheckResult, EvidenceState, AuthorityLevel\n\nGRADE_LABELS = {\n    \"A\": \"Governance-Optimized\",\n    \"B\": \"Managed\",\n    \"C\": \"Defined\",\n    \"D\": \"Repeatable\",\n    \"E\": \"Initial / Absent\",\n}\n\n\ndef compute_score(results: list[CheckResult]) -> tuple[int, str, bool]:\n    \"\"\"Compute score, grade, and gate from check results.\n\n    Only checks with a weight > 0 contribute to the score. File-size\n    discipline checks should have weight=0 to appear in the report\n    without affecting the governance score.\n    \"\"\"\n    scoring_checks = [r for r in results if r.weight > 0]\n    total_weight = sum(r.weight for r in scoring_checks)\n    earned = sum(r.weight for r in scoring_checks if r.passed)\n    score = round(earned / total_weight * 100) if total_weight > 0 else 0\n\n    if score >= 90:\n        grade = \"A\"\n    elif score >= 80:\n        grade = \"B\"\n    elif score >= 70:\n        grade = \"C\"\n    elif score >= 60:\n        grade = \"D\"\n    else:\n        grade = \"E\"\n\n    gate_passed = all(r.passed for r in scoring_checks if r.blocking)\n    return score, grade, gate_passed\n\n\ndef recommend_authority(results: list[CheckResult]) -> AuthorityLevel:\n    \"\"\"Recommend maximum agent authority based on evidence states.\n\n    A public-only report must never recommend autonomous merge or release\n    when enforcement settings are unobservable. Authority is capped by\n    the weakest blocking evidence state.\n    \"\"\"\n    has_unobservable = False\n    has_claimed_only = False\n    has_detected = False\n    has_enforced = False\n\n    for r in results:\n        if not r.blocking or r.weight == 0:\n            continue\n        if r.state == EvidenceState.UNOBSERVABLE:\n            has_unobservable = True\n        elif r.state == EvidenceState.ABSENT:\n            return AuthorityLevel.UNSAFE\n        elif r.state == EvidenceState.CLAIMED:\n            has_claimed_only = True\n        elif r.state == EvidenceState.DETECTED:\n            has_detected = True\n        elif r.state == EvidenceState.ENFORCED:\n            has_enforced = True\n        elif r.state == EvidenceState.VERIFIED:\n            has_enforced = True\n\n    if has_unobservable:\n        return AuthorityLevel.OWNER_EVIDENCE_REQUIRED\n    if has_claimed_only:\n        return AuthorityLevel.UNSAFE\n    if has_detected and not has_enforced:\n        return AuthorityLevel.PR_ONLY_PROVISIONAL\n    if has_enforced:\n        return AuthorityLevel.LOCAL_ONLY\n    return AuthorityLevel.UNSAFE","rung.sources":"\"\"\"Cited sources for Rung governance checks.\n\nEach source is classified by authority level. Rung is \"informed by\"\nstandards and industry practices, not every check is directly derived\nfrom a standard.\n\"\"\"\n\nfrom rung.models import SourceClass\n\nSOURCES = {\n    \"agents_md\": {\n        \"name\": \"agents.md (Linux Foundation / AAIF)\",\n        \"url\": \"https://agents.md\",\n        \"note\": \"Cross-vendor agent policy spec, adopted by 60k+ repos. \"\n                \"Defines AGENTS.md as the de-facto agent instruction file.\",\n        \"classification\": SourceClass.STANDARD,\n    },\n    \"github_copilot\": {\n        \"name\": \"GitHub Copilot repository custom instructions\",\n        \"url\": \"https://docs.github.com/en/copilot/customizing-copilot/adding-repository-custom-instructions-for-github-copilot\",\n        \"note\": \"Official GitHub docs for .github/copilot-instructions.md and \"\n                \"AGENTS.md precedence (nearest file in directory tree wins).\",\n        \"classification\": SourceClass.PLATFORM_CONTROL,\n    },\n    \"nist_rmf\": {\n        \"name\": \"NIST AI Risk Management Framework 1.0\",\n        \"url\": \"https://nist.gov/itl/ai-risk-management-framework\",\n        \"note\": \"US government framework. Four functions: Govern, Map, \"\n                \"Measure, Manage. Voluntary but widely adopted.\",\n        \"classification\": SourceClass.STANDARD,\n    },\n    \"anthropic_multiagent\": {\n        \"name\": \"Anthropic \u2014 How we built our multi-agent research system\",\n        \"url\": \"https://www.anthropic.com/engineering/multi-agent-research-system\",\n        \"note\": \"Production guidance on agent evaluation: LLM-as-judge rubrics, \"\n                \"end-state evaluation, durable execution, checkpointing.\",\n        \"classification\": SourceClass.VENDOR_GUIDANCE,\n    },\n    \"openai_codex\": {\n        \"name\": \"openai/codex AGENTS.md (exemplar)\",\n        \"url\": \"https://github.com/openai/codex/blob/main/AGENTS.md\",\n        \"note\": \"322-line root AGENTS.md with 500/800 LoC thresholds, \"\n                \"change-size guidance, mandatory integration tests.\",\n        \"classification\": SourceClass.EXEMPLAR,\n    },\n    \"apache_airflow\": {\n        \"name\": \"apache/airflow AGENTS.md (exemplar)\",\n        \"url\": \"https://github.com/apache/airflow/blob/main/AGENTS.md\",\n        \"note\": \"522-line AGENTS.md with Generated-by attribution, \"\n                \"Drafted-by footer, Never-rules, apache-magpie framework.\",\n        \"classification\": SourceClass.EXEMPLAR,\n    },\n    \"ibm_adlc\": {\n        \"name\": \"IBM \u2014 Agent Development Lifecycle\",\n        \"url\": \"https://www.ibm.com/think/topics/agent-development-lifecycle-adlc\",\n        \"note\": \"Trace layer concept: every AI agent needs an action \"\n                \"accountability trace.\",\n        \"classification\": SourceClass.VENDOR_GUIDANCE,\n    },\n    \"slsa\": {\n        \"name\": \"SLSA v1.2 (Supply-chain Levels for Software Artifacts)\",\n        \"url\": \"https://slsa.dev/spec/v1.2/\",\n        \"note\": \"OpenSSF standard for build provenance. Applies to \"\n                \"agent-produced artifacts.\",\n        \"classification\": SourceClass.STANDARD,\n    },\n    \"iso_42001\": {\n        \"name\": \"ISO/IEC 42001:2023 \u2014 AI management system standard\",\n        \"url\": \"https://www.iso.org/standard/83730.html\",\n        \"note\": \"Certifiable AI Management System standard. Plan-do-check-act \"\n                \"for AI.\",\n        \"classification\": SourceClass.STANDARD,\n    },\n    \"github_branch_protection\": {\n        \"name\": \"GitHub REST API \u2014 Branch Protection\",\n        \"url\": \"https://docs.github.com/en/rest/branches/branch-protection\",\n        \"note\": \"Branch protection settings require Administration read \"\n                \"permission even for read operations on public repos.\",\n        \"classification\": SourceClass.PLATFORM_CONTROL,\n    },\n    \"openssf_scorecard\": {\n        \"name\": \"OpenSSF Scorecard\",\n        \"url\": \"https://scorecard.dev/\",\n        \"note\": \"Each check explains its risk, scoring logic, evidence, \"\n                \"remediation, and limitations. Model for Rung's check format.\",\n        \"classification\": SourceClass.INDUSTRY_PRACTICE,\n    },\n}\n\nSOURCE_EXTENSIONS = {\".py\", \".swift\", \".gd\", \".ts\", \".tsx\", \".js\", \".jsx\", \".go\", \".rs\", \".java\", \".kt\", \".rb\"}\nIGNORED_PARTS = {\".git\", \"build\", \"dist\", \"node_modules\", \"DerivedData\", \".venv\", \"venv\", \".build\", \"Pods\", \"target\", \"__pycache__\"}\n\nWATCH_LOC = 500\nSMELL_LOC = 800\nDEFECT_LOC = 1200"}


class _BundledLoader(importlib.abc.MetaPathFinder, importlib.abc.Loader):
    def find_spec(self, fullname, path=None, target=None):
        if fullname not in _SOURCES:
            return None
        is_package = fullname == "rung" or any(
            name.startswith(fullname + ".") for name in _SOURCES
        )
        return importlib.util.spec_from_loader(fullname, self, is_package=is_package)

    def create_module(self, spec):
        return None

    def exec_module(self, module):
        module.__file__ = "<rung-single-file>/" + module.__name__.replace(".", "/") + ".py"
        exec(compile(_SOURCES[module.__name__], module.__file__, "exec"), module.__dict__)


import sys
sys.meta_path.insert(0, _BundledLoader())

from rung.cli import main

if __name__ == "__main__":
    raise SystemExit(main())
